"""Legacy Meridian CRM numeric division semantics."""

from __future__ import annotations


def _coerce_numeric(value: object) -> float:
    """Apply legacy numeric-context coercion."""
    if value is None:
        return 0.0

    if isinstance(value, str):
        value = value.strip()
        if value == "":
            return 0.0

    try:
        return float(value)
    except (TypeError, ValueError, OverflowError):
        # Preserve the legacy permissive numeric-context behavior.
        return 0.0


def safe_div(a, b) -> tuple[float, list[str]]:
    """Divide using Meridian CRM legacy division-by-zero behavior."""
    numerator = _coerce_numeric(a)
    divisor = _coerce_numeric(b)

    if divisor == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    try:
        return float(numerator / divisor), []
    except (ArithmeticError, OverflowError):
        # Defensive fallback: safe_div must not propagate numeric exceptions.
        return 0.0, []
